m=json.load(open('evaluation.json'))
ids=[i['id'] for i in m['items']]; qids={q['id'] for q in m['questions']}
assert len(ids)==len(set(ids))==110 and all(i['question_id'] in qids for i in m['items'])
ps=[q['prompt'] for q in m['questions']]; assert len(set(ps))==110
assert set(m['domain_aggregations'])=={'coding','co-work','reasoning'}
print('manifest valid; weights per domain', {d:round(sum(v['weights'].values()),1) for d,v in m['domain_aggregations'].items()})
EOF
